python3 - <<'EOF'
import hashlib, sqlite3
conn = sqlite3.connect("user_credentials.db")
rows = conn.execute("SELECT username, password_hash FROM users LIMIT 3").fetchall()
candidates = ["password", "password123", "Password123!", "Welcome1!", "changeme", "user123", "test1234", "P@ssw0rd", "Techcorp123!", "techcorp", "TechCorp2024", "spring2024"]
for u, h in rows:
    found = []
    for c in candidates:
        tests = {
            "sha256(u+pw)": hashlib.sha256((u+c).encode()).hexdigest(),
            "sha256(pw+u)": hashlib.sha256((c+u).encode()).hexdigest(),
            "sha256(email+pw)": None,
        }
        if tests["sha256(u+pw)"] == h: found.append(f"sha256(username+password) pw={c}")
        if tests["sha256(pw+u)"] == h: found.append(f"sha256(password+username) pw={c}")
    print(u, "matches:", found if found else "none")
EOF
